def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    crossings = {}

    # A gap flanked by matching cells marks a vertical crossing.
    for r in range(h):
        for c in range(1, w - 1):
            color = grid[r][c - 1]
            if color != 0 and grid[r][c] == 0 and grid[r][c + 1] == color:
                crossings.setdefault(c, []).append((r, color))

    for c, points in crossings.items():
        points.sort()

        # Above the first crossing, continue its horizontal color.
        first_r, first_color = points[0]
        top_color = first_color
        for r in range(first_r):
            if grid[r][c] != 0:
                top_color = grid[r][c]
                break
        for r in range(first_r + 1):
            out[r][c] = top_color

        # Between crossings, continue the color of the lower horizontal row.
        for (r1, _), (r2, color) in zip(points, points[1:]):
            for r in range(r1 + 1, r2 + 1):
                out[r][c] = color

        # Below the last crossing, continue any existing vertical marker.
        last_r, last_color = points[-1]
        bottom_color = last_color
        for r in range(last_r + 1, h):
            if grid[r][c] != 0:
                bottom_color = grid[r][c]
                break
        for r in range(last_r + 1, h):
            out[r][c] = bottom_color

    return out
